let storage,profile,mode='survival',difficulty='normal',lastSave=0,lastSaveOk=true;
function applyProfileSelection(){mode=profile.selection.mode||'survival';difficulty=profile.selection.difficulty||'normal';selected=Math.max(0,CHARACTERS.findIndex(c=>c.id===profile.selection.character));mapIndex=Math.max(0,MAPS.findIndex(m=>m.id===profile.selection.map));}
function flushProgress(){
 if(!profile)return;if(game)creditRun(profile,game);
 if(storage?.batch){const entries=new Map(),stage={setItem:(key,value)=>entries.set(key,String(value)),removeItem:key=>entries.set(key,null)};try{if(!saveProfile(profile,stage))throw Error();if(game){const saved=saveRun(game,stage);if(game.status!=='over'&&game.p.hp>0&&!saved)throw Error();}storage.batch([...entries].filter(([key])=>!key.endsWith('.backup')));lastSaveOk=true;}catch{lastSaveOk=false;}}
 else{lastSaveOk=saveProfile(profile,storage);if(game){const saved=saveRun(game,storage);if(game.status!=='over'&&game.p.hp>0)lastSaveOk=lastSaveOk&&saved;}}
 updateSaveNotice();
}
function updateSaveNotice(){const notice=$('.save-notice');if(!notice)return;const state=storage?.status?.();notice.textContent=lastSaveOk&&state?.persistent!==false?(state?.recovered?'Recovered your local backup. Your progress is saved on this device.':'Progress and unfinished runs save automatically on this device.'):'Local saving is unavailable. Open Save & Backup to export your progress.';}
window.addEventListener('pagehide',()=>{audioPlayer.stop();flushProgress();});document.addEventListener('visibilitychange',()=>{if(document.hidden){audioPlayer.stop();flushProgress();}});
const reducedMotion=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
function readBest(){try{return Math.max(profile.bestKills||0,Number(storage?.getItem('anime-best')||0));}catch{return profile.bestKills||0;}}
function tone(){if(sound)audioPlayer.effect('ui');}
function syncAudio(){if(!profile)return;sound=!profile.audio.muted;audioPlayer.setSettings(profile.audio);const b=$('#sound');if(b){b.setAttribute('aria-pressed',String(sound));b.setAttribute('aria-label',sound?'Mute music and sounds':'Enable music and sounds');b.innerHTML=sound?'♪':'♫';}const master=$('#audio-master');if(master)master.textContent=sound?'MUTE ALL AUDIO':'ENABLE AUDIO';}
function toggleSound(){profile.audio.muted=!profile.audio.muted;syncAudio();audioPlayer.unlock();saveProfile(profile,storage);}
function audioSettings(){return `<div class="audio-settings"><button id="audio-master" type="button">${profile.audio.muted?'ENABLE AUDIO':'MUTE ALL AUDIO'}</button><label>MUSIC<input id="music-volume" type="range" min="0" max="100" value="${Math.round(profile.audio.music*100)}"><output id="music-value">${Math.round(profile.audio.music*100)}%</output></label><label>SOUND EFFECTS<input id="sfx-volume" type="range" min="0" max="100" value="${Math.round(profile.audio.sfx*100)}"><output id="sfx-value">${Math.round(profile.audio.sfx*100)}%</output></label></div>`;}
function bindAudioSettings(){const master=$('#audio-master');if(!master)return;master.onclick=toggleSound;for(const [id,key]of [['music','music'],['sfx','sfx']]){$('#'+id+'-volume').oninput=e=>{profile.audio[key]=Number(e.target.value)/100;$('#'+id+'-value').textContent=e.target.value+'%';syncAudio();audioPlayer.unlock();};$('#'+id+'-volume').onchange=()=>saveProfile(profile,storage);}}
const recipeIngredientName=(f,id)=>id===f.weapon&&f.requiresEvolution?FUSIONS.find(other=>other.id===f.requiresEvolution).name:ITEMS[id].name;
const recipeArt=f=>{const ingredients=fusionIngredients(f),art=ingredients.map(id=>icon(id===f.weapon&&f.requiresEvolution?f.requiresEvolution:id)).join('<span>+</span>');return f.resultItem?`<span class="soul-gem-ingredients composite-ingredients" aria-label="${ingredients.length} maxed passive ingredients">${art}</span>`:art;};
function compositeRecipeIndex(){
 const recipes=FUSIONS.filter(f=>f.resultItem);
 return `<section class="composite-index" aria-label="Complete passive sets"><span class="small-label">COMBINE A COMPLETE SET</span><p>Train every ingredient, then unite its bonuses in one passive slot.</p><div>${recipes.map(f=>`<button type="button" data-recipe-jump="${f.id}" style="--item:${f.color}" aria-label="Show ${f.name} recipe">${icon(f.id)}<span><strong>${f.name}</strong><small>${fusionIngredients(f).length} MAXED ITEMS · ONE SLOT</small></span></button>`).join('')}</div></section>`;
}
function madokaFusionProfile(character){
 if(character.id!=='madoka')return '';
 const names=['Madoka','Sayaka','Mami','Kyoko','Homura'];
 return `<div class="soul-gem-profile" data-soul-gem-profile><span class="soul-gem-label">COMBINE THE GEMS / EVOLVE THE BOW</span><h3>Five wishes. One miracle.</h3><div class="soul-gem-quintet">${SOUL_GEM_IDS.map((id,i)=>`<span style="--gem:${ITEMS[id].color}">${icon(id)}<small>${names[i]}</small></span>`).join('')}</div><div class="soul-gem-stage">${icon('quintet')}<div><small>01 / FUSE FIVE MAXED GEMS</small><strong>Soul Gems of the Quintet</strong><span>All five bonuses in one passive slot.</span></div></div><div class="soul-gem-evolution" aria-label="Ultimate Madoka plus Soul Gems of the Quintet evolves into Salvation">${icon('ultimate')}<span>+</span>${icon('quintet')}<span>→</span>${icon('salvation')}<b>Salvation</b></div><p>Fuse the five LV 3 gems into <b>Soul Gems of the Quintet</b>. Then combine this item with the LV 5 <b>Ultimate Madoka</b> bow for <b>Salvation: Five Wishes</b>. You can make the Quintet before or after the bow’s first evolution. Both fusions use normal level-up, chest and Boss Rush choices.</p><small class="soul-gem-mode">THE QUINTET STAYS EQUIPPED AFTER SALVATION</small><button type="button" class="soul-gem-guide" id="soul-gem-guide">VIEW THE FUSION CHAIN <span aria-hidden="true">→</span></button></div>`;
}
function itemChip(id,label,look=null){const item=ITEMS[id];return `<div class="signature-item" style="--item:${item.color}"><span class="item-art">${icon(look?.icon||id)}</span><div><small>${label}</small><strong>${look?.name||item.name}</strong></div></div>`;}
function ultimateProfile(character){
 const abilities=[{...ULTIMATES[character.id],icon:SPECIAL_ICONS[character.id],cooldown:ULTIMATE_COOLDOWN,controls:'SPACE / SPECIAL BUTTON'}];
 if(character.id==='frieren')abilities.push({...FRIEREN_BARRAGE,controls:'E / BARRAGE BUTTON · SEPARATE COOLDOWN'});
 return abilities.map((ability,i)=>`<div class="ultimate-profile" data-ultimate="${i?'frieren-barrage':character.id}" role="group" aria-label="${character.name} ${i?'second ultimate':'ultimate'}" style="--ultimate-color:${ability.color}"><div class="ultimate-profile-heading"><span class="ultimate-profile-icon">${icon(ability.icon)}</span><div><small>${i?'SECOND ULTIMATE':'ULTIMATE ABILITY'}</small><h3>${ability.name}</h3></div><span class="ultimate-profile-cooldown">${ability.cooldown}s<small>BASE COOLDOWN</small></span></div><p>${ability.description}</p><span class="ultimate-profile-controls">${ability.controls}</span></div>`).join('');
}
function prestigeProfile(character){
 const state=prestigeState(profile,character.id);
 return `<div class="hero-prestige-note"><button class="prestige-trigger ${state.canPrestige?'ready':''}" id="profile-prestige">✦ PRESTIGE ${state.rank} / ${state.max}</button><span>${state.atCap?'Highest prestige reached.':state.canPrestige?'Your mastery is complete. Review your prestige rewards.':'Max this hero’s mastery tree to earn permanent bonuses.'}</span></div>`;
}
const modeName=value=>value==='hardcore'?'HARDCORE':value==='bossrush'?'BOSS RUSH':'SURVIVAL';
function requipProfile(character){
 if(character.id!=='erza')return '';
 return `<div class="requip-profile"><div><small>BASE FORM / THREE ARMORS</small><strong>Choose the armor for the fight.</strong><p>Press R or tap REQUIP in battle to cycle armor. Switching has a short cooldown; weapon rank and evolution carry across all forms.</p></div><div class="requip-forms">${[3,0,1,2].map(i=>{const form=ERZA_FORMS[i],weapon=erzaWeaponAppearance({p:{id:'erza'},mechanic:{form:i}});return `<article style="--form-color:${form.color}">${portrait(character,'default',i)}<strong>${form.name}</strong><span class="requip-form-weapon">${icon(weapon.icon)}<span>${weapon.name}</span></span><p>${form.description}</p></article>`;}).join('')}</div></div>`;
}
