  flushProgress();audioPlayer.setScene({playing:false,paused:true});input?.dispose();input=null;game=null;renderedStatus='';const savedRun=loadRun(storage),c=CHARACTERS[selected],f=FUSIONS.find(f=>f.weapon===c.weapon&&!f.requiresEvolution);
  app.innerHTML=`<div class="shell"><header><a class="brand" href="#" aria-label="Anime Survivors home"><span class="brand-icon">✦</span> ANIME<span class="brand-light">SURVIVORS</span><span class="beta">PIXEL RIFT / ${CHARACTERS.length}</span></a><nav><button class="nav-button active" id="play-tab">PLAY</button><button class="nav-button" id="arsenal">ARSENAL <span>${Object.keys(ITEMS).length}</span></button><button class="nav-button" id="bestiary">BESTIARY</button><button class="nav-button" id="progression">SKILL TREES</button><button class="nav-button" id="tier-list">TIER LIST</button><button class="nav-button" id="save-manager">SAVE & BACKUP</button><button id="sound" class="icon-button" aria-label="Toggle sound" aria-pressed="${sound}">${sound?'♪':'♫'}</button></nav></header><main><section class="intro"><div><div class="eyebrow"><i></i> ${MAPS.length} WORLDS. ONE LAST STAND.</div><h1>LEGENDS NEVER<br><span>FIGHT ALONE.</span></h1><p>Build your power. Fuse your weapons. Break every limit.</p></div><div class="season-note"><span class="small-label">THE RIFT IS EVOLVING</span><strong>FIND YOUR <em>PERFECT FUSION.</em></strong><div>${recipeArt(f)}<span>→</span><span class="fusion-mini">${icon(f.id)}</span></div><p>${fusionType(f)==='passive'?'Max both passives to combine their powers.':f.weapon2?(f.passive?'Max both weapons + the matching passive to awaken a fusion.':'Max both weapons to awaken a two-item fusion.'):'Max a weapon + its passive to awaken a fusion.'}</p></div></section><section class="mode-picker" aria-label="Game mode"><button data-mode="survival" class="mode-card ${mode==='survival'?'selected':''}" aria-pressed="${mode==='survival'}"><span class="mode-mark">${icon('shuriken')}</span><span><small>GROW YOUR BUILD</small><strong>Survival</strong><span>Endless hordes, boss waves and optional superboss rifts.</span></span><b>${mode==='survival'?'✓':'+'}</b></button><button data-mode="bossrush" class="mode-card boss-rush-mode ${mode==='bossrush'?'selected':''}" aria-pressed="${mode==='bossrush'}"><span class="mode-mark">${icon('power')}</span><span><small>RANDOM MAXED UPGRADES</small><strong>Boss Rush</strong><span>${REGULAR_BOSS_IDS.length} bosses. Level into a full-power build.</span></span><b>${mode==='bossrush'?'✓':'+'}</b></button><button data-mode="hardcore" class="mode-card hardcore-mode ${mode==='hardcore'?'selected':''}" aria-pressed="${mode==='hardcore'}"><span class="mode-mark">${icon('odmblades')}</span><span><small>MASTER YOUR SIGNATURE</small><strong>Hardcore</strong><span>Only your character’s weapons and passive. Upgrade and evolve your signature build.</span></span><b>${mode==='hardcore'?'✓':'+'}</b></button></section><section class="difficulty-picker"><div><label for="difficulty">DIFFICULTY / ${difficultyFor(difficulty).name.toUpperCase()}</label><p>${difficultyFor(difficulty).description}</p></div><select id="difficulty" aria-label="Game difficulty">${DIFFICULTIES.map(d=>`<option value="${d.id}" ${difficulty===d.id?'selected':''}>${d.name}</option>`).join('')}</select></section><section class="legend-selection" id="character-select" aria-labelledby="legend-heading">${selectionTools()}<section class="roster" id="character-roster" aria-label="Characters">${characterCards(profile,selected)}</section><div class="roster-empty" id="roster-empty" hidden><strong>No legends found.</strong><p>Try a character, anime, weapon or ultimate name.</p><button type="button" id="reset-roster">SHOW ALL LEGENDS</button></div></section><section class="selected-loadout" id="character-profile" tabindex="-1" aria-label="Selected character profile" style="--accent:${c.color}">${selectedProfileHeading(c,profile)}<div class="profile-content"><div class="hero-summary"><span class="small-label">${c.name.toUpperCase()}’S STARTING LOADOUT</span><p>${c.description}</p><p class="trait-note"><b>${HERO_MECHANICS[c.id].name}</b> ${HERO_MECHANICS[c.id].description}</p>${requipProfile(c)}${ultimateProfile(c)}${madokaFusionProfile(c)}${prestigeProfile(c)}</div><div class="profile-equipment"><span class="small-label">STARTING EQUIPMENT</span><div class="signature-pair">${itemChip(c.weapon,(c.formWeapon?'HUMAN FORM':'WEAPON')+(mode==='bossrush'?' · LV 5':' · LV 1'),c.id==='erza'?erzaWeaponAppearance({p:{id:'erza'}}):null)}${c.formWeapon?itemChip(c.formWeapon,mode==='bossrush'?'TITAN FORM · LV 5':'TITAN FORM · LV 1'):''}${c.secondWeapon?itemChip(c.secondWeapon,mode==='bossrush'?'WEAPON · LV 5':'WEAPON · LV 1'):''}${itemChip(c.passive,mode==='bossrush'?'PASSIVE · LV 3':'PASSIVE · LV 1')}</div><button class="fusion-link" id="fusion-guide">${icon('fusion')}<span>FUSION RECIPES</span><b>${icon('arrow')}</b></button></div></div></section><section class="skin-picker"><div><span class="small-label">APPEARANCE / ${skinFor(c.id,profile.skins[c.id]).name.toUpperCase()}</span><p>Cosmetic skins · same skills and mastery · all available</p></div><div class="skin-options">${SKINS[c.id].map(skin=>`<button class="skin-option ${skinFor(c.id,profile.skins[c.id]).id===skin.id?'active':''}" data-skin="${skin.id}" aria-pressed="${skinFor(c.id,profile.skins[c.id]).id===skin.id}">${portrait(c,skin.id)}<span>${skin.name}</span></button>`).join('')}</div></section><section class="pet-picker"><div><span class="small-label">COMPANION / ${petFor(profile.pet).name.toUpperCase()}</span><p>Just company. Pets never attack, block enemies or collect loot.</p></div><div class="pet-options">${PETS.map(pet=>`<button class="pet-option ${pet.id===profile.pet?'active':''}" data-pet="${pet.id}" aria-pressed="${pet.id===profile.pet}" title="${pet.description}">${petSvg(pet.id)}<span>${pet.name}</span></button>`).join('')}</div></section><div class="section-heading map-heading" id="map-selection" tabindex="-1" aria-label="Choose your battleground"><h2><span>02 /</span> CHOOSE YOUR BATTLEGROUND</h2><span>${mode==='bossrush'?'BOSSES ONLY · MAP SETS BOSS ORDER':'ENDLESS WAVES · BOSS EVERY 5 WAVES'}</span></div><section class="maps">${MAPS.map((map,i)=>`<button class="map-card ${mapIndex===i?'selected':''}" data-map="${i}" style="--map:${map.color}" aria-pressed="${mapIndex===i}"><div class="map-art">${mapPreview(map)}</div><div class="map-info"><div><span>${map.tag}</span><strong>${map.name}</strong></div><span class="map-check">${i===mapIndex?'✓':icon('arrow')}</span></div></button>`).join('')}</section>${savedRun?`<section class="continue-run"><div><span class="small-label">SAVED RUN</span><strong>${savedRun.mode==='survival'?'':modeName(savedRun.mode)+' · '}${savedRun.p.displayName} · ${savedRun.map.name} · ${formatTime(savedRun.time)}</strong><small>${savedRun.mode==='bossrush'?savedRun.rush.cleared+' / '+savedRun.rush.total+' bosses cleared':'Level '+savedRun.p.level+' · '+savedRun.kills+' defeated'} · resumes paused</small></div><button class="secondary" id="continue-run">CONTINUE SAVED RUN</button></section>`:''}<section class="launch"><div class="run-meta"><span class="status-dot"></span><div><strong>${mode==='bossrush'?'THE GAUNTLET IS READY':mode==='hardcore'?'YOUR SIGNATURE IS ALL YOU NEED':'THE RIFT IS READY'}</strong><small>${mode==='bossrush'?'Random maxed upgrades · fill every slot · fuse and fight':mode==='hardcore'?'Your weapons and passive only · matching evolutions':'1 HP/s · 1 reroll · 1 ban · '+FUSIONS.length+' fusions'}</small></div></div><button class="primary" id="start">${mode==='bossrush'?'ENTER BOSS RUSH':mode==='hardcore'?'ENTER HARDCORE':'ENTER THE RIFT'} <span>${icon('arrow')}</span><small>${c.name.toUpperCase()} / ${MAPS[mapIndex].name.toUpperCase()}</small></button></section><p class="save-notice" role="status">${lastSaveOk?'Progress and unfinished runs save automatically on this device.':'Local saving is unavailable. Open Save & Backup to export your progress.'}</p><footer><span><kbd>WASD</kbd> MOVE <i></i><kbd>SPACE</kbd> SPECIAL <i></i><kbd>SHIFT</kbd> DASH <i></i> PINCH / SCROLL TO ZOOM</span><span>PERSONAL BEST <b>${readBest()}</b> DEFEATED</span></footer></main>${selectionDock(c,profile)}</div><div id="menu-modal"></div>`;
  $('[data-character="'+selected+'"]').classList.add('chosen');
