  if(p.id!=='shinji')$('.hero-hud .avatar').innerHTML=icon(p.id==='samus'?cannonAppearance(game).icon:p.id==='erza'?erzaWeaponAppearance(game).icon:(p.fusions[p.weapon]||p.weapon));
