function clearControls(){input?.reset();}
function togglePause(){if(!game)return;if($('#close-tier-list')){$('#close-tier-list').click();return;}if(game.status==='playing'){game.status='paused';clearControls();showPause();}else if(game.status==='paused')resume();}
function showPause(){
  flushProgress();renderedStatus='paused';$('#modal').innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-label="Game paused"><span class="eyebrow">TAKE A BREATH</span><h2>Time stands still.</h2><p>${game.mode==='bossrush'?'BOSS RUSH · '+game.rush.cleared+' / '+game.rush.total+' BOSSES CLEARED<br>':''}${game.mode==='hardcore'?'HARDCORE · YOUR WEAPONS & PASSIVE ONLY<br>':''}${game.map.name} · ${difficultyFor(game.difficulty).name} · ${formatTime(game.time)} survived<br>WASD / drag to move · pinch or scroll to zoom<br>H to show / hide the interface<br>Space for your ultimate · Shift / L to dash${game.p.id==='erza'?' · R to Requip':game.p.id==='frieren'?' · E for Annihilation Barrage (75s base)':''}<br>Ultimate: 60s base cooldown · enemies strengthen each minute<br>Bosses resist 20% of incoming damage<br>Move + dash + special with separate fingers<br>Break supplies for food, coins and magnets<br>${Math.floor(game.money)} coins + ${Math.floor(game.characterXp)} character XP earned · kept when you leave</p>${audioSettings()}<button class="primary" id="resume">RESUME RUN ${icon('arrow')}</button><button class="secondary" id="pause-tier-list">VIEW TIER LISTS</button><button class="secondary" id="pause-save-manager">SAVE & BACKUP</button><button class="secondary" id="exit">RETURN TO LOBBY</button></section></div>`;bindAudioSettings();$('#resume').onclick=resume;$('#pause-tier-list').onclick=()=>openTierList(true);$('#pause-save-manager').onclick=()=>openSaveManager(true);$('#exit').onclick=menu;$('#resume').focus();
}
function resume(){clearControls();const pending=game.resumeStatus;delete game.resumeStatus;if(pending&&pending!=='playing'){game.status=pending;renderedStatus='';$('#modal').innerHTML='';return;}if(game.mode!=='bossrush'&&takeLevel(game.p)){game.status='upgrade';renderedStatus='';showLevel();return;}game.status='playing';renderedStatus='playing';$('#modal').innerHTML='';flushProgress();}
function showItem(id){
 if(game.status!=='playing')return;game.status='paused';clearControls();renderedStatus='paused';
 const p=game.p,fused=p.fusions[id],recipes=FUSIONS.filter(f=>fusionIngredients(f).includes(id)||f.weapon===id),f=FUSIONS.find(f=>f.id===fused)||recipes[0],look=p.id==='samus'&&id==='powerbeam'?cannonAppearance(game):p.id==='erza'&&id==='requip'?erzaWeaponAppearance(game):null,item=ITEMS[id],description=(p.id==='erza'&&id==='requip'?look.description+' ':'')+(fused?f.description:item.description)+(p.id==='samus'&&look?' Evolution at 100 / 200 / 300 kills adds Wave, Ice and Plasma.':'');
 $('#modal').innerHTML=`<div class="modal-backdrop"><section class="modal item-detail" role="dialog" aria-modal="true" aria-label="Item details" style="--item:${fused?f.color:item.color}"><span class="large-item">${icon(look?.icon||fused||id)}</span><span class="eyebrow">${item.type.toUpperCase()} · ${fused?'FUSED':'LEVEL '+(item.type==='weapon'?p.weapons:p.passives)[id]}</span><h2>${look?.name||(fused?f.name:item.name)}</h2><p>${description}</p>${(fused?[f,...recipes.filter(recipe=>recipe.id!==f.id)]:recipes).map(recipe=>`<div class="detail-recipe">${recipeArt(recipe)} → ${icon(recipe.id)}<small>${fusionRequirement(recipe)}</small></div>`).join('')}<button class="primary" id="resume">BACK TO THE FIGHT ${icon('arrow')}</button></section></div>`;$('#resume').onclick=resume;$('#resume').focus();
}

function choiceContent(choice){
  if(choice.kind==='fusion'){const f=FUSIONS.find(f=>f.id===choice.id),look=game.p.id==='erza'&&f.id==='heavensarsenal'?erzaWeaponAppearance(game,{fused:true}):null;return {name:f.name,id:look?.icon||f.id,color:f.color,label:'FUSION AWAKENING',text:fusionDescription(f),sub:fusionIngredients(f).map(id=>recipeIngredientName(f,id)).join(' + '),action:'FUSE & EVOLVE'};}
  if(choice.kind==='heal')return {name:'Second Wind',id:'heal',color:'#eaa0ae',label:'RECOVERY',text:'Restore 50 health. Your journey continues.',sub:'INSTANT HEAL',action:'RECOVER'};
  const item=ITEMS[choice.id],look=game.p.id==='samus'&&choice.id==='powerbeam'?cannonAppearance(game):game.p.id==='erza'&&choice.id==='requip'?erzaWeaponAppearance(game):null,owned=(item.type==='weapon'?game.p.weapons:game.p.passives)[choice.id];
  return {name:look?.name||item.name,id:look?.icon||choice.id,color:look?.color||item.color,label:choice.maxLevel?'MAXED '+item.type.toUpperCase()+' · LV '+item.max:`${owned?'UPGRADE':'NEW '+item.type.toUpperCase()} · LV ${choice.level} / ${item.max}`,text:(game.p.id==='erza'&&choice.id==='requip'?look.description+' ':'')+(owned?item.scaling:item.description),sub:item.owner?`${item.owner.toUpperCase()}’S SIGNATURE ${item.type.toUpperCase()}`:item.type.toUpperCase(),action:choice.maxLevel?'CLAIM AT MAX LEVEL':owned?'LEVEL UP':'ADD TO LOADOUT'};
}
function showLevel(){
  if(renderedStatus===game.status)return;flushProgress();clearControls();renderedStatus=game.status;const fusionOnly=game.status==='fusion';
  const choices=game.levelChoices??(fusionOnly?FUSIONS.filter(f=>fusionReady(game.p,f)).map(f=>({kind:'fusion',id:f.id})).slice(0,3):getChoices(game.p));game.levelChoices=choices;const canReroll=game.p.rerollsLeft>0&&!fusionOnly&&getUpgradePool(game.p).some(c=>!choices.some(old=>old.id===c.id)),canVanish=game.p.vanishesLeft>0&&!fusionOnly&&choices.some(c=>c.kind==='item');
  $('#modal').innerHTML=`<div class="modal-backdrop"><section class="modal upgrade-modal" role="dialog" aria-modal="true" aria-label="Choose an upgrade"><span class="eyebrow">${fusionOnly?'RIFT CACHE · FUSION UNLOCKED':'LEVEL '+game.p.level+' / YOUR POWER GROWS'}</span><h2>${fusionOnly?'Awaken your potential.':'Go beyond.'}</h2><p>Choose your next power. Every combination tells a different story.</p><div class="upgrades">${choices.map((choice,i)=>{const c=choiceContent(choice);return `<button class="upgrade ${choice.kind==='fusion'?'fusion-choice':''}" data-choice="${i}" ${game.vanishArmed&&choice.kind!=='item'?'disabled':''} style="--item:${c.color}"><span class="upgrade-label">${c.label}</span><span class="upgrade-art">${icon(c.id)}</span><small class="upgrade-origin">${c.sub}</small><strong>${c.name}</strong><p>${c.text}</p><b>${game.vanishArmed?'BAN FROM RUN':c.action} <span>${icon('arrow')}</span></b></button>`;}).join('')}</div><div class="upgrade-controls"><button id="reroll" class="secondary" ${canReroll?'':'disabled'}>REROLL · ${game.p.rerollsLeft}</button><button id="vanish" class="secondary ${game.vanishArmed?'armed':''}" ${canVanish?'':'disabled'}>${game.vanishArmed?'CANCEL BAN':'BAN · '+game.p.vanishesLeft}</button></div><small class="upgrade-hint">${game.vanishArmed?'SELECT AN ITEM TO BAN FROM THIS RUN. YOUR LEVEL-UP IS KEPT.':'Every run starts with 1 Reroll + 1 Ban. Upgrade both in the shared tree.'}</small><small class="upgrade-hint">${game.mode==='hardcore'?'YOUR WEAPONS & PASSIVE ONLY · EVOLUTIONS AVAILABLE':'5 WEAPON SLOTS · 5 PASSIVE SLOTS · MATCH MAXED ITEMS TO FUSE'}</small></section></div>`;
  document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{
    const choice=choices[+b.dataset.choice];if(game.vanishArmed){if(choice.kind==='fusion'||choice.kind==='heal'||!vanishItem(game.p,choice.id))return;game.levelChoices=getChoices(game.p);game.vanishArmed=false;renderedStatus='';showLevel();return;}if(!applyChoice(game.p,choice))return;tone(choice.kind==='fusion'?700:500);burst(game,game.p.x,game.p.y,choice.kind==='fusion'?'#ffd69f':'#c5a6ff',45);
    if(choice.kind==='fusion'){game.toast='FUSION AWAKENED · '+FUSIONS.find(f=>f.id===choice.id).name.toUpperCase();game.toastTime=4;game.shake=8;}
    game.levelChoices=null;game.vanishArmed=false;inventoryKey='';resume();updateHud();
  });$('#reroll').onclick=()=>{const next=rerollChoices(game.p,choices);if(next){game.levelChoices=next;game.vanishArmed=false;renderedStatus='';showLevel();}};$('#vanish').onclick=()=>{game.vanishArmed=!game.vanishArmed;renderedStatus='';showLevel();};document.querySelector('[data-choice]')?.focus();tone(600);
}
function showRift(){
 if(renderedStatus==='rift')return;renderedStatus='rift';clearControls();flushProgress();
 const choose=enter=>{if(!resolveRift(game,enter))return;clearControls();renderedStatus='';$('#modal').innerHTML='';updateHud();flushProgress();};
 showRiftOffer($('#modal'),game,{onEnter:()=>choose(true),onLeave:()=>choose(false)});
}
function showChest(){
  if(renderedStatus==='chest')return;renderedStatus='chest';clearControls();inventoryKey='';inventory();
  const run=game,rewards=game.rewards,index=game.chestIndex||0,choice=rewards[index],content=choice?choiceContent(choice):null,variant=game.chestKind||'normal',isRift=variant==='rift',isEvent=variant==='event',source=game.chestSource||'TREASURE CACHE',title=isEvent?'The event is conquered.':isRift?'A relic beyond the rift.':variant==='mimic'?'The treasure is yours.':'Something worth the fight.';
  // This checkpoint belongs to the cache, so taking or ignoring the next item
  // never restarts the animation. A restored unfinished reveal is safe to skip.
  if(reducedMotion||index>0||!content)game.chestOpeningComplete=true;
  const opening=content&&!game.chestOpeningComplete;
  flushProgress();
  if(opening){
    tone(460);
    $('#modal').innerHTML=`<div class="modal-backdrop"><section class="modal chest-modal ${isRift?'rift-treasure':''}" role="dialog" aria-modal="true" aria-label="Opening treasure chest"><span class="eyebrow">${source.toUpperCase()} · ${isEvent?'WORLD EVENT CLEARED':isRift?'RIFT RELIC':'TREASURE CHEST'}</span><div class="chest-opening is-opening"><div class="chest-art-stage">${chestIllustration({variant})}</div><span class="chest-opening-copy">THE SEAL BREAKS · YOUR REWARD AWAITS</span><div class="chest-progress" aria-hidden="true"></div><p>No item is equipped until you choose it.</p><button class="secondary" id="skip-chest-opening">SKIP OPENING</button></div></section></div>`;
    const stage=$('.chest-opening');
    const reveal=()=>{if(game!==run||game.status!=='chest'||!stage.isConnected)return;game.chestOpeningComplete=true;renderedStatus='';tone(790);showChest();};
    $('#skip-chest-opening').onclick=reveal;$('#skip-chest-opening').focus({preventScroll:true});setTimeout(reveal,1200);return;
  }
  $('#modal').innerHTML=`<div class="modal-backdrop"><section class="modal chest-modal ${isRift?'rift-treasure':''} ${content?'':'chest-resolved'}" role="dialog" aria-modal="true" aria-label="Choose chest rewards"><span class="eyebrow">${source.toUpperCase()} · ${isEvent?'WORLD EVENT CLEARED':isRift?'RIFT RELIC':variant==='mimic'?'RECLAIMED TREASURE':'TREASURE CHEST'}</span><div class="chest-art-stage">${chestIllustration({variant,stage:'open'})}</div><h2>${content?title:'Chest resolved.'}</h2><p class="reward-index">${content?'REWARD '+(index+1)+' / '+rewards.length+' · Available evolutions are offered first.':'Your choices are saved. Ignored items leave your loadout unchanged.'}</p>${content?`<article class="chest-offer" style="--item:${content.color}"><span class="large-item">${icon(content.id)}</span><small>${content.label}</small><h3>${content.name}</h3><p>${content.text}</p><div class="chest-choice-actions"><button class="primary" id="take-reward">${choice.kind==='fusion'?'AWAKEN FUSION':'TAKE REWARD'}</button><button class="secondary" id="ignore-reward">IGNORE THIS ITEM</button></div></article><button class="secondary" id="ignore-chest">IGNORE ALL REMAINING</button>`:`<div class="chest-rewards">${rewards.map(c=>`<article class="chest-reward"><span class="item-art">${icon(c.id)}</span><strong>${choiceContent(c).name}</strong><small>${c.decision==='taken'?'TAKEN':'IGNORED'}</small></article>`).join('')}</div><button class="primary" id="claim">CONTINUE THE RUN ${icon('arrow')}</button>`}<small class="chest-odds">${isEvent?'3 GUARANTEED REWARD CHOICES':isRift?'5 GUARANTEED REWARD CHOICES':'1 / 3 / 5 REWARDS'} · NOTHING IS EQUIPPED WITHOUT YOUR CHOICE</small></section></div>`;
  const redraw=()=>{flushProgress();renderedStatus='';showChest();updateHud();};
  if(content){$('#take-reward').onclick=()=>{if(resolveChestReward(game,true))redraw();};$('#ignore-reward').onclick=()=>{resolveChestReward(game,false);redraw();};$('#ignore-chest').onclick=()=>{ignoreChest(game);redraw();};$('#take-reward').focus({preventScroll:true});}
  else{$('#claim').onclick=()=>{resume();updateHud();};$('#claim').focus({preventScroll:true});}
}

function showTrinketDrop(){
 if(renderedStatus==='trinket')return;clearControls();renderedStatus='trinket';flushProgress();
 if(!renderTrinketOffer($('#modal'),game,{onResolved:()=>{inventoryKey='';renderedStatus='';tone(510);if(game.status==='wish'){updateHud();showWish();return;}resume();updateHud();flushProgress();}})){game.status='playing';resume();}
}
function showWish(){
 if(renderedStatus==='wish')return;clearControls();renderedStatus='wish';flushProgress();
 if(!showShenronWish($('#modal'),game,{onResolved:()=>{inventoryKey='';renderedStatus='';tone(720);burst(game,game.p.x,game.p.y,'#f0d796',42);resume();updateHud();flushProgress();}})){game.status='playing';resume();}
}
function showTrinketInfo(slot){
 if(game.status!=='playing'||game.bossIntro)return;game.status='paused';renderedStatus='paused';clearControls();flushProgress();
 showTrinketDetails($('#modal'),game,slot,{onResume:()=>{resume();updateHud();},onChange:()=>{inventoryKey='';flushProgress();},onUseEvent:slot=>{
  if(!activateEventTrinket(game,slot))return false;
  clearControls();renderedStatus='playing';inventoryKey='';$('#modal').innerHTML='';updateHud();flushProgress();return true;
 }});
}

function showEnd(){
  if(renderedStatus==='over')return;flushProgress();clearControls();renderedStatus='over';let best=readBest();try{storage?.setItem('anime-best',String(Math.max(best,game.kills)));}catch{}
  const won=game.won;$('#modal').innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-label="Run results"><span class="eyebrow">${won?'RIFT SEALED':'THE RIFT CLAIMS ANOTHER'}</span><h2>${game.mode==='bossrush'?(won?'The gauntlet is yours.':'The gauntlet remembers.'):won?'A legend survives.':'Your next chapter awaits.'}</h2><p>${game.mode==='bossrush'?game.rush.cleared+' / '+game.rush.total+' bosses defeated. '+(won?'Every challenger has fallen.':'Your earned coins and character XP are saved.'):won?'The guardian has fallen. Your world lives another day.':'Every run is a chance to discover a new combination.'}</p><div class="results"><div><strong>${formatTime(game.time)}</strong><span>SURVIVED</span></div><div><strong>${game.kills}</strong><span>DEFEATED</span></div><div><strong>${Math.floor(game.money)}</strong><span>COINS BANKED</span></div></div><p>${Math.floor(game.characterXp)} ${game.p.name.toUpperCase()} XP BANKED · LEVEL ${game.p.level} · ${game.bossKills} BOSSES DEFEATED · ${game.broken} OBJECTS BROKEN · PERSONAL BEST ${Math.max(best,game.kills)} DEFEATED</p><button class="primary" id="retry">RUN IT BACK ${icon('arrow')}</button><button class="secondary" id="exit">CHOOSE YOUR LEGEND</button></section></div>`;$('#retry').onclick=()=>{mode=game.mode;start();};$('#exit').onclick=menu;$('#retry').focus();
}
function skipIntro(){finishBossIntro(game);clearControls();syncBossIntro();}
function syncBossIntro(){
 const intro=game.bossIntro;const host=$('#boss-intro');host.hidden=game.status!=='playing';if(shownIntro===intro?.id){updateBossIntroVisual(host,intro,reducedMotion);return;}
 shownIntro=intro?.id;clearControls();host.innerHTML=intro?bossIntroMarkup(intro):'';
 $('.arena').classList.toggle('cinema-active',!!intro);updateBossIntroVisual(host,intro,reducedMotion);
 if(intro){$('#skip-intro').onclick=skipIntro;$('#skip-intro').focus();}else{$('#game').tabIndex=0;$('#game').focus({preventScroll:true});}
}
window.addEventListener('keydown',e=>{if(game?.status==='playing'&&game.bossIntro&&['Space','Enter','Escape'].includes(e.code)){e.preventDefault();e.stopImmediatePropagation();skipIntro();}});
function frame(ts){
  const dt=Math.min((ts-last)/1000,.04);last=ts;
  if(game){if(game.status==='playing'){const oldKills=game.kills;updateRun(game,dt,input.direction());if(game.kills>oldKills)tone(240);updateHud();if(game.time-lastSave>=5){flushProgress();lastSave=game.time;}}
    if(game.status==='over'&&!game.won&&game.p.hp<=0){if(!game.playerDeath)queuePlayerDeath(game);if(game.playerDeath?.age===0){clearControls();updateHud();}if(!document.hidden)updateFriendlyDeaths(game,dt);}
    if(game.checkpointRequested){delete game.checkpointRequested;flushProgress();lastSave=game.time;}
    audioPlayer.setScene({playing:game.status==='playing',paused:game.status!=='playing',boss:game.enemies.some(e=>e.boss&&e.hp>0)||!!game.bossIntro,rift:!!game.riftArena,mapId:game.riftArena?.id||game.map.id});audioPlayer.update(game,dt);
    syncBossIntro();drawScene($('#game'),game,reducedMotion);
    if(game.status==='rush-loadout'||game.status==='rush-draft'||game.status==='rush-fusion')showRushSetup();else if(game.status==='upgrade'||game.status==='fusion')showLevel();else if(game.status==='rift')showRift();else if(game.status==='chest')showChest();else if(game.status==='trinket')showTrinketDrop();else if(game.status==='wish')showWish();else if(game.status==='over'&&!playerDeathPending(game))showEnd();
  }requestAnimationFrame(frame);
}
async function boot(){
 app.innerHTML='<main class="save-loading" role="status">Loading your local progress…</main>';
 try{storage=await openSaveStorage();}catch{storage=undefined;}
 profile=loadProfile(storage);syncAudio();applyProfileSelection();menu();requestAnimationFrame(frame);
}
boot();
